//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is safe to retry.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut attempt = 0;

    loop {
        attempt += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= max_attempts => {
                return Err(error);
            }
            Err(_) => {
                sleeper.sleep_ms(retry_delay(config, attempt));
            }
        }
    }
}

fn retry_delay(config: &RetryConfig, retry_number: u32) -> u64 {
    let base_delay = config.base_delay_ms.min(config.max_delay_ms);
    let doublings = retry_number.saturating_sub(1);

    if base_delay == 0 {
        return 0;
    }

    let delay = base_delay
        .checked_shl(doublings)
        .unwrap_or(config.max_delay_ms);
    delay.min(config.max_delay_ms)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn delay_growth_is_bounded() {
        let config = RetryConfig {
            max_attempts: 5,
            base_delay_ms: 3,
            max_delay_ms: 10,
        };
        assert_eq!(retry_delay(&config, 1), 3);
        assert_eq!(retry_delay(&config, 2), 6);
        assert_eq!(retry_delay(&config, 3), 10);
        assert_eq!(retry_delay(&config, 4), 10);
    }

    #[test]
    fn delay_calculation_does_not_overflow() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: 1,
            max_delay_ms: 100,
        };
        assert_eq!(retry_delay(&config, u32::MAX), 100);
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

fn config(max_attempts: u32) -> RetryConfig {
    RetryConfig {
        max_attempts,
        base_delay_ms: 10,
        max_delay_ms: 25,
    }
}

#[test]
fn retries_transient_errors_until_success() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(4), &mut sleeper, || {
        calls += 1;
        if calls < 3 {
            Err(RetryError::Transient("temporary outage".into()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![10, 20]);
}

#[test]
fn permanent_errors_return_without_retrying() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(4), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("invalid job".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid job".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn attempt_limit_includes_first_call_and_delays_are_capped() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(4), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("still unavailable".into()))
    });

    assert_eq!(
        result,
        Err(RetryError::Transient("still unavailable".into()))
    );
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps, vec![10, 20, 25]);
}

#[test]
fn public_policy_saturates_for_large_attempt_numbers() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let config = RetryConfig {
        max_attempts: u32::MAX,
        base_delay_ms: 1,
        max_delay_ms: 100,
    };

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls < 66 {
            Err(RetryError::Transient("temporary outage".into()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 66);
    assert_eq!(sleeper.sleeps.len(), 65);
    assert!(sleeper.sleeps[63..].iter().all(|&delay| delay == 100));
}

#[test]
fn zero_attempt_budget_still_makes_one_call() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(0), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("failure".into()))
    });

    assert!(matches!(result, Err(RetryError::Transient(_))));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}
